import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Aiiot.css'; // Ensure CSS is applied

const ResourcesPage = () => {
  // ==============================
  // 1. NAVIGATION STATE
  // ==============================
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [projectsDropdownOpen, setProjectsDropdownOpen] = useState(false);
  const [mobileLaunchesExpanded, setMobileLaunchesExpanded] = useState(false);

  // ==============================
  // 2. DATA STATE
  // ==============================
  const [groupedResources, setGroupedResources] = useState({
    vision: [],
    center: [],
    setup: [],
    report: [],
    other: []
  });
  const [loading, setLoading] = useState(true);
  
  const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000';

  // ==============================
  // 3. EFFECT: CLICK OUTSIDE (NAV)
  // ==============================
  useEffect(() => {
    const handleClickOutside = (event) => {
      const navElement = document.querySelector('nav');
      if (navElement && !navElement.contains(event.target)) {
        setProjectsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // ==============================
  // 4. EFFECT: FETCH & GROUP DATA
  // ==============================
  useEffect(() => {
    const fetchResources = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/api/brochures/`);
        const data = await response.json();
        const results = data.results || data;

        // Initialize groups based on your Django Model Choices
        const groups = {
          vision: [],
          center: [],
          setup: [],
          report: [],
          other: []
        };

        if (results && results.length > 0) {
          results.forEach(item => {
            // Ensure absolute URL
            const fileUrl = item.file.startsWith('http') ? item.file : `${API_BASE_URL}${item.file}`;
            
            const formattedItem = {
              id: item.id,
              title: item.title,
              description: item.description,
              category: item.category,
              url: fileUrl,
              icon: item.icon || '📄',
              date: new Date(item.created_at).toLocaleDateString()
            };

            // Sort into categories
            if (groups[item.category]) {
              groups[item.category].push(formattedItem);
            } else {
              groups.other.push(formattedItem); // Fallback for unknown categories
            }
          });
        }
        setGroupedResources(groups);
      } catch (error) {
        console.error('Error fetching resources:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchResources();
  }, [API_BASE_URL]);

  // ==============================
  // 5. HELPER: RENDER SECTION
  // ==============================
  const renderSection = (title, items, icon) => {
    if (!items || items.length === 0) return null;
    return (
      <section style={{ marginBottom: '4rem' }}>
        <h2 style={{ 
          fontSize: '2rem', 
          fontWeight: 700, 
          color: '#1e293b', 
          marginBottom: '1.5rem', 
          borderLeft: '5px solid #3b82f6', 
          paddingLeft: '1rem',
          display: 'flex',
          alignItems: 'center',
          gap: '10px'
        }}>
          <span>{icon}</span> {title}
        </h2>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1.5rem' }}>
          {items.map((item) => (
            <div key={item.id} style={{ 
              background: 'white', 
              border: '1px solid #e2e8f0', 
              borderRadius: '0.75rem', 
              padding: '1.5rem', 
              boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'space-between'
            }}>
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                    <span style={{ fontSize: '1.5rem' }}>{item.icon}</span>
                    <span style={{ fontSize: '0.75rem', color: '#94a3b8' }}>{item.date}</span>
                </div>
                <h4 style={{ fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', marginBottom: '0.5rem' }}>{item.title}</h4>
                <p style={{ color: '#64748b', fontSize: '0.9rem', lineHeight: '1.5' }}>{item.description}</p>
              </div>
              <a 
                href={item.url} 
                target="_blank" 
                rel="noopener noreferrer" 
                style={{ 
                  display: 'block', 
                  marginTop: '1.5rem', 
                  padding: '0.5rem', 
                  textAlign: 'center', 
                  background: '#eff6ff', 
                  color: '#3b82f6', 
                  textDecoration: 'none', 
                  borderRadius: '0.375rem', 
                  fontWeight: 600,
                  border: '1px solid #bfdbfe',
                  transition: 'background 0.2s'
                }}
                onMouseEnter={(e) => e.target.style.background = '#dbeafe'}
                onMouseLeave={(e) => e.target.style.background = '#eff6ff'}
              >
                Download PDF ⬇️
              </a>
            </div>
          ))}
        </div>
      </section>
    );
  };

  return (
    <div className="aiiot-page-container">
      {/* ===================================================== */}
      {/* INTEGRATED NAVIGATION BAR                             */}
      {/* ===================================================== */}
      <header style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        height: '5rem',
        zIndex: 1000,
        width: '100%',
        backgroundColor: 'rgba(255, 255, 255, 0.95)',
        backdropFilter: 'blur(20px)',
        borderBottom: '1px solid rgba(226, 232, 240, 0.5)',
        boxShadow: '0 4px 30px rgba(0, 0, 0, 0.08)'
      }}>
        <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 1.5rem' }}>
          <nav style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', height: '5rem' }}>
            
            {/* LOGO (Redirects to Home) */}
            <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '1rem', zIndex: 1001, textDecoration: 'none' }}>
              <div style={{
                width: 'auto', height: '3.25rem', borderRadius: '0.5rem', background: '#ffffff',
                display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0.25rem',
                boxShadow: '0 3px 10px rgba(0, 0, 0, 0.12)', border: '1px solid #e2e8f0'
              }}>
                <img src="/logo/logo.png" alt="Adi Shankara Institute" style={{ height: '100%', width: 'auto' }} />
              </div>
              <div style={{ display: 'flex', flexDirection: 'column' }}>
                <span style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b', lineHeight: 1.2 }}>
                  AI-IoT Innovations
                </span>
                <span className="logo-text-secondary" style={{ fontSize: '0.75rem', color: '#64748b', fontWeight: 500 }}>
                  Adi Shankara Engineering Institute
                </span>
              </div>
            </Link>

            {/* DESKTOP NAVIGATION */}
            <div className="desktop-nav">
              <a href="/#about" style={{ fontSize: '0.875rem', fontWeight: 500, color: '#475569', textDecoration:'none' }} 
                 onMouseEnter={(e) => e.target.style.color = '#3b82f6'} onMouseLeave={(e) => e.target.style.color = '#475569'}>
                 About
              </a>
              <a href="/#team" style={{ fontSize: '0.875rem', fontWeight: 500, color: '#475569', textDecoration:'none' }}
                 onMouseEnter={(e) => e.target.style.color = '#3b82f6'} onMouseLeave={(e) => e.target.style.color = '#475569'}>
                 Team
              </a>

              {/* Resources (Active State) */}
              <Link to="/resources" style={{ fontSize: '0.875rem', fontWeight: 600, color: '#3b82f6', textDecoration: 'none' }}>
                Resources
              </Link>

              <a href="/#projects" style={{ fontSize: '0.875rem', fontWeight: 500, color: '#475569', textDecoration:'none' }}
                 onMouseEnter={(e) => e.target.style.color = '#3b82f6'} onMouseLeave={(e) => e.target.style.color = '#475569'}>
                 Projects
              </a>

              {/* Launches Dropdown */}
              <div style={{ position: 'relative' }}>
                <button
                  onClick={() => setProjectsDropdownOpen(!projectsDropdownOpen)}
                  style={{ fontSize: '0.875rem', fontWeight: 500, color: '#475569', background: 'transparent', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.25rem' }}
                  onMouseEnter={(e) => e.currentTarget.style.color = '#3b82f6'} onMouseLeave={(e) => e.currentTarget.style.color = '#475569'}
                >
                  Launches <span style={{ fontSize: '0.75rem' }}>▼</span>
                </button>
                {projectsDropdownOpen && (
                  <div style={{ position: 'absolute', top: '100%', right: 0, marginTop: '0.5rem', background: 'white', borderRadius: '0.5rem', boxShadow: '0 10px 25px rgba(0,0,0,0.15)', border: '1px solid #e2e8f0', minWidth: '14rem', zIndex: 100 }}>
                     <Link to="/homepage" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '0.75rem 1rem', textDecoration: 'none', color: '#1e293b' }}>
                        <span style={{ fontSize: '1.25rem' }}>🌬️</span>
                        <div><div style={{fontWeight:600, fontSize:'0.9rem'}}>AirAware</div><div style={{fontSize:'0.75rem', color:'#64748b'}}>Air Monitor</div></div>
                     </Link>
                     <a href="/weather-home" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '0.75rem 1rem', textDecoration: 'none', color: '#1e293b', borderTop:'1px solid #f1f5f9' }}>
                        <span style={{ fontSize: '1.25rem' }}>💧</span>
                        <div><div style={{fontWeight:600, fontSize:'0.9rem'}}>AWS Link</div><div style={{fontSize:'0.75rem', color:'#64748b'}}>Water Monitor</div></div>
                     </a>
                  </div>
                )}
              </div>

              <a href="/#contact" style={{ padding: '0.625rem 1.25rem', background: '#3b82f6', color: 'white', fontSize: '0.875rem', fontWeight: 600, borderRadius: '0.5rem', textDecoration:'none' }}>
                Get in Touch
              </a>
            </div>

            {/* MOBILE HAMBURGER BUTTON */}
            <button className="mobile-nav-toggle" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
              {isMobileMenuOpen ? '✕' : '☰'}
            </button>
          </nav>
        </div>

        {/* MOBILE MENU */}
        {isMobileMenuOpen && (
          <div className="mobile-menu-wrapper">
            <a href="/#about" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9' }}>About</a>
            <a href="/#team" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9' }}>Team</a>
            
            <Link to="/resources" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#3b82f6', borderBottom: '1px solid #f1f5f9' }}>
              Resources
            </Link>

            <a href="/#projects" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9' }}>Projects</a>

            <div style={{ borderBottom: '1px solid #f1f5f9', marginBottom:'2rem' }}>
              <button onClick={() => setMobileLaunchesExpanded(!mobileLaunchesExpanded)}
                style={{ width: '100%', display: 'flex', justifyContent: 'space-between', padding: '1rem 0', background: 'none', border: 'none', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b' }}>
                Launches <span>{mobileLaunchesExpanded ? '−' : '+'}</span>
              </button>
              {mobileLaunchesExpanded && (
                <div className="mobile-submenu">
                  <Link to="/homepage" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '0.75rem 0', color: '#1e293b', fontWeight:500 }}>🌬️ AirAware Monitor</Link>
                  <a href="/weather-home" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '0.75rem 0', color: '#1e293b', fontWeight:500 }}>💧 AWS Water Monitor</a>
                </div>
              )}
            </div>
            <a href="/#contact" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', width: '100%', padding: '1rem', background: '#3b82f6', color: 'white', textAlign: 'center', borderRadius: '0.5rem', fontWeight: 600, fontSize: '1.1rem' }}>
              Get in Touch
            </a>
          </div>
        )}
      </header>

      {/* ===================================================== */}
      {/* MAIN CONTENT                                          */}
      {/* ===================================================== */}
      <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '7rem 1rem 3rem 1rem' }}>
        
        <h1 style={{ fontSize: '2.5rem', fontWeight: 800, color: '#1e293b', textAlign: 'center', marginBottom: '1rem' }}>
          Resource Center
        </h1>
        <p style={{ textAlign: 'center', color: '#64748b', marginBottom: '4rem', fontSize: '1.1rem' }}>
          Access all official documents, guides, and reports from the Center for AI-IoT.
        </p>

        {loading ? (
          <div style={{ textAlign: 'center', color: '#64748b', padding: '4rem' }}>Loading resources...</div>
        ) : (
          <>
            {/* 1. Vision & Mission Section */}
            {renderSection("Vision & Mission", groupedResources.vision, "🎯")}

            {/* 2. Center Brochures Section */}
            {renderSection("Center Brochures", groupedResources.center, "🏢")}

            {/* 3. Setup Guides Section */}
            {renderSection("Setup Guides", groupedResources.setup, "⚙️")}

            {/* 4. Annual Reports Section */}
            {renderSection("Annual Reports", groupedResources.report, "📊")}

            {/* 5. Other Resources */}
            {renderSection("Other Resources", groupedResources.other, "📁")}

            {/* Empty State */}
            {Object.values(groupedResources).every(arr => arr.length === 0) && (
              <div style={{ textAlign: 'center', color: '#94a3b8', padding: '4rem', background: '#f8fafc', borderRadius: '1rem' }}>
                <p>No resources have been uploaded yet.</p>
              </div>
            )}
          </>
        )}

        <div style={{textAlign: 'center', marginTop: '4rem', borderTop: '1px solid #e2e8f0', paddingTop: '2rem'}}>
          <Link to="/" style={{color: '#64748b', textDecoration: 'none', fontWeight: 500}}>← Back to Home</Link>
        </div>
      </div>
    </div>
  );
};

export default ResourcesPage;
